func JWTAuth(tokenSvc TokenService, blacklist Blacklist) gin.HandlerFunc {
  return func(c *gin.Context) {
    raw := extractBearer(c)
    claims, err := tokenSvc.Verify(raw) // 校验签名(kid)与 exp
    if err != nil { respondUnauthorized(c, ErrTokenInvalid); return }
    if blocked, _ := blacklist.Contains(claims.JTI); blocked { respondUnauthorized(c, ErrTokenRevoked); return }
    c.Set("user_id", claims.Subject)
    c.Next()
  }
}

type PasswordService interface {
  Hash(plain string) (hash string, algo string, err error)
  Compare(hash, plain string) bool
  CheckHistory(userID, plain string) (reused bool, err error)
}

func (s *passwordService) Hash(plain string) (string, string, error) {
  switch s.cfg.Algo {
  case "argon2id":
    return argon2idHash(plain, s.cfg.Argon2Params), "argon2id", nil
  default:
    b, err := bcrypt.GenerateFromPassword([]byte(plain), s.cfg.BcryptCost) // cost >= 10
    return string(b), "bcrypt", err
  }
}

func RateLimit(limiter Limiter, policyResolver PolicyResolver) gin.HandlerFunc {
  return func(c *gin.Context) {
    p := policyResolver.Resolve(c.FullPath())
    key := p.Scope + ":" + c.FullPath() + ":" + identity(c, p.Scope)
    allowed, retryAfter := limiter.Allow(key, p.LimitCount, p.WindowSeconds)
    if !allowed {
      c.Header("Retry-After", strconv.Itoa(retryAfter))
      respondTooManyRequests(c, ErrRateLimited)
      return
    }
    c.Next()
  }
}

type Blacklist interface {
  Add(jti string, ttl time.Duration) error
  Contains(jti string) (bool, error)
}

func (b *redisBlacklist) Add(jti string, ttl time.Duration) error {
  return b.rdb.Set(ctx, "bl:"+jti, 1, ttl).Err()
}

func (h *LoginHandler) Login(c *gin.Context) {
  var req LoginRequest
  if err := c.ShouldBindJSON(&req); err != nil { respondBadRequest(c, ErrInvalidParam); return }
  user, err := h.authSvc.Authenticate(req.Email, req.Password, c.ClientIP(), c.Request.UserAgent())
  if err != nil { respondUnauthorized(c, err); return }
  access, exp, _ := h.tokenSvc.IssueAccessToken(user.ID)
  refresh, rexp, _ := h.tokenSvc.IssueRefreshToken(user.ID, c.ClientIP(), c.Request.UserAgent())
  h.audit.Publish("user_login", user.ID, c.ClientIP())
  respondOK(c, LoginResponse{AccessToken: access, RefreshToken: refresh, TokenType: "Bearer", ExpiresIn: exp, RefreshExpiresIn: rexp})
}

func (h *RegisterHandler) Register(c *gin.Context) {
  var req RegisterRequest
  if err := c.ShouldBindJSON(&req); err != nil { respondBadRequest(c, ErrInvalidParam); return }
  if !validateEmail(req.Email) { respondBadRequest(c, ErrEmailInvalid); return }
  if !validatePasswordComplexity(req.Password) { respondBadRequest(c, ErrPasswordWeak); return }
  hash, algo, _ := h.passwordSvc.Hash(req.Password)
  user, err := h.userRepo.Create(req.Email, hash, algo)
  if isDuplicate(err) { respondConflict(c, ErrEmailExists); return }
  h.audit.Publish("user_registered", user.ID, c.ClientIP())
  respondCreated(c, RegisterResponse{UserID: user.ID, Email: user.Email, CreatedAt: user.CreatedAt})
}

func (h *LogoutHandler) Logout(c *gin.Context) {
  claims := getClaims(c)
  ttl := time.Until(claims.ExpiresAt.Time)
  h.tokenSvc.Revoke(claims.ID, ttl)
  if req.RefreshToken != "" { h.tokenSvc.RevokeRefresh(req.RefreshToken, "logout") }
  h.audit.Publish("user_logout", claims.Subject, c.ClientIP())
  respondOK(c, LogoutResponse{Success: true})
}

var (
  httpRequests = prometheus.NewCounterVec(prometheus.CounterOpts{Name: "auth_http_requests_total"}, []string{"endpoint", "status"})
  httpLatency  = prometheus.NewHistogramVec(prometheus.HistogramOpts{Name: "auth_http_latency_seconds"}, []string{"endpoint"})
  tokensIssued = prometheus.NewCounter(prometheus.CounterOpts{Name: "auth_tokens_issued_total"})
)

func Register() { prometheus.MustRegister(httpRequests, httpLatency, tokensIssued) }

